const message = `<div class="shadowdark">
<h2 >THE VAMPIRE THRALLS OF TLACAETICA HAVE ESCAPED FROM THEIR MONOLITH PRISONS</h2>
</div>`;

const chatData = {
	user: game.user._id,
	flavor: "Announcement",
	content: message,
};

ChatMessage.create(chatData, {});

const dialogContent = `
<form class="shadowdark" autocomplete="off" spellcheck="off">
    <div class="form-group">
        <h3>Select Player Vice</h3>
        <select name="vice">
            <option value="TEMPLE OF FESTIVALS">The Bottle</option>
			<option value="TEMPLE OF LUST">The Boudoir</option>
			<option value="TEMPLE OF THE HUNT">The Feast</option>
			<option value="TEMPLE OF COMMUNION">The Pipe</option>
        </select>
    </div>
    <hr />
</form>
`;

//open prompt
const dialogData = {
    title: "Temple Collapse",
    content: dialogContent,
    buttons: {
        button1: {
            label: "Select",
            callback: async html => {
                const temple = html.find("[name=vice]")?.val();
				const message = `<div class="shadowdark">
					<h2>THE ${temple} IN THE CITY OF GOLD HAS COLLAPSED</h2>
					</div>`;
				const chatData = {
					user: game.user._id,
					flavor: "Announcement",
					content: message,
				};
				ChatMessage.create(chatData, {});
            },
        },
    },
}
await Dialog.wait(dialogData);

const message = `<div class="shadowdark">
<h2 >KNEEL, SPEAK YOUR GREED, AND PRAY THE STAR-EATER FINDS YOU WORTHY</h2>
</div>`;

const chatData = {
	user: game.user._id,
	flavor: "A Magic Mouth",
	content: message,
};

ChatMessage.create(chatData, {});
